valid.tests/ui/live/post-login-home-navigation:
import { expect, test } from "@playwright/test";

// Journey: journey:company-directory
// Layer: assembly
// URN: test:journey:company-directory:RESP-001-recovers-home-navigation

const VIEWPORTS = [375, 768, 1280];
for (const width of VIEWPORTS) test(`company directory at ${width}px`, async ({ page }) => {
  await page.setViewportSize({ width, height: 900 });
  await page.goto("/");
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  expect(overflow).toBeLessThanOrEqual(0);
});

